-- Notification delivery and digest jobs (#196, #23 part 3).
--   * notification_setting holds a member's per-workspace delivery settings (`court_hours_quiet`,
--     the `Do not push during court hours` toggle). A tenant table built with tenantTable(): FORCE
--     RLS and the standard ws_isolation policy (tenantPolicy()), registered in the cross-tenant suite.
--   * app_notification_digest_targets() lists the live workspaces and their timezone (ids and zone
--     only) for the workspace-less `system.notification.digest` scheduler. organization and
--     workspace_settings are under FORCE RLS, so this is an owner-defined SECURITY DEFINER function,
--     the same pattern as app_billing_reconcile_targets (0007). owner_definer_read on
--     workspace_settings lets only the owner (and so only definer functions) read it; organization
--     already has the policy (0006). The per-workspace digest job then reads inside withWorkspace.
-- New table, policy and function only: nothing existing is altered or dropped.
CREATE TABLE "notification_setting" (
	"user_id" uuid NOT NULL,
	"court_hours_quiet" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "notification_setting_pkey" PRIMARY KEY("workspace_id","user_id")
);
