CREATE FUNCTION app_notification_digest_targets()
  RETURNS TABLE (workspace_id uuid, timezone text)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT o.id, coalesce(s.timezone, 'Asia/Kolkata') FROM organization o
    LEFT JOIN workspace_settings s ON s.workspace_id = o.id
    WHERE o.deleted_at IS NULL
    ORDER BY o.id
  $$;--> statement-breakpoint
